<?php
defined('ABSPATH') || exit;
/** Actual performed sale linked to an unchanged larger source budget. */
final class GE_Work_History_Scope {
    const META='_ge_historical_performed_scope';
    public static function create($source_id,$selected) {
        if(!GE_Work_Historical_Reconciliation::allowed())throw new RuntimeException('Acceso denegado.');
        $selected=array_values(array_unique(array_map('absint',$selected)));sort($selected,SORT_NUMERIC);if(!$selected)throw new DomainException('Seleccioná los renglones efectivamente realizados.');
        $key='ge_commercial_reconcile_order_'.absint($source_id);if(!GE_Work_Finance::lock($key))throw new RuntimeException('El presupuesto está siendo procesado.');$started=false;$sale=null;
        try {
            GE_Work_History_Storage::begin($source_id,array(),array());$started=true;$source=GE_Work_Finance::strict_order($source_id);$source->read_meta_data(true);GE_Work_History_Storage::check();$declaration=GE_Work_Historical_Reconciliation::source($source);if(!$declaration)throw new DomainException('No hay una confirmación única de este presupuesto.');$r=$declaration['row'];
            if($r['commercial']!=='partial' || $r['payment']!=='paid_scope' || !is_int($r['performed_cents']) || $r['performed_cents']<=0 || $r['performed_cents']!==$r['collected_cents'])throw new DomainException('Esta operación requiere un alcance parcial realizado e importe confirmado.');
            $expected=$declaration['expected_fingerprints']['order_id:'.$source_id]??'';if(!$expected || !hash_equals($expected,GE_Work_Historical_Reconciliation::source_fingerprint('order_id',$source_id)))throw new DomainException('Cambió el presupuesto de origen.');
            $existing=absint($source->get_meta('_ge_historical_scope_order_id',true));if($existing){$sale=wc_get_order($existing);$proof=$sale?$sale->get_meta(self::META,true):array();if(!$sale || ($proof['source_revision']??'')!==$declaration['revision'] || ($proof['source_key']??'')!==$r['key'] || ($proof['selected_items']??array())!==$selected)throw new DomainException('Ya hay otro alcance vinculado; revisá la ficha.');GE_Work_History_Storage::commit();$started=false;return $sale;}
            $balance=GE_Work_Finance::balance($source);GE_Work_History_Storage::check();if(is_wp_error($balance) || $balance['amount_paid_cents']!==0)throw new DomainException('Hay movimientos previos en el presupuesto; no se moverá ni duplicará dinero.');
            $before=GE_Work_Historical_Reconciliation::snapshot($source);$chosen=array();$net=0;$tax=0;
            foreach($selected as $id){$item=$source->get_item($id);GE_Work_History_Storage::check();if(!$item || $item->get_meta('_ge_item_status',true)==='cancelled')throw new DomainException('Renglón de origen no válido.');$item->read_meta_data(true);GE_Work_History_Storage::check();$chosen[$id]=$item;$net+=GE_WTP_Quote_Balance::cents(wc_format_decimal($item->get_total(),2));$tax+=GE_WTP_Quote_Balance::cents(wc_format_decimal($item->get_total_tax(),2));}
            $adjustment=$r['performed_cents']-$net-$tax;if($adjustment && (count($chosen)!==1 || $tax!==0))throw new DomainException('El precio de los renglones no coincide con lo realizado; requiere revisar el alcance.');
            $sale=wc_create_order(array('customer_id'=>$source->get_customer_id()));if(is_wp_error($sale))throw new RuntimeException('No se pudo crear el alcance realizado.');$sale->set_currency($source->get_currency());$sale->set_address($source->get_address('billing'),'billing');$sale->set_address($source->get_address('shipping'),'shipping');$sale->set_created_via('ge_historical_performed_scope');$map=array();
            foreach($chosen as $id=>$old){$item=new WC_Order_Item_Product();$item->set_name($old->get_name());$item->set_product_id($old->get_product_id());$item->set_quantity($old->get_quantity());$item->set_subtotal($old->get_subtotal());$item->set_total($old->get_total());$item->set_taxes($old->get_taxes());foreach(array('Configuración','Especificaciones','Unidad','_ge_quote_unit','_ge_quote_unit_net_cents','_ge_internal_roll_width_cm') as $meta){$v=$old->get_meta($meta,true);if($v!=='')$item->update_meta_data($meta,$v);}$item->update_meta_data('_ge_historical_source_item_id',$id);$item->update_meta_data('_ge_item_status','pending');$sale->add_item($item);$item->save();GE_Work_History_Storage::check();$map[(string)$id]=$item->get_id();}
            if($adjustment){$fee=new WC_Order_Item_Fee();$fee->set_name('Ajuste del precio final confirmado del alcance realizado');$fee->set_amount(GE_WTP_Quote_Balance::decimal($adjustment));$fee->set_total(GE_WTP_Quote_Balance::decimal($adjustment));$sale->add_item($fee);}
            $sale->calculate_totals(false);$sale->set_total(GE_WTP_Quote_Balance::decimal($r['performed_cents']));$sale->update_meta_data('_ge_historical_scope_source_order_id',$source_id);$sale->update_meta_data('_ge_work_label',$r['customer']);$sale->save();GE_Work_History_Storage::check();
            $transferred=array();foreach($chosen as $id=>$old){$child_id=absint($old->get_meta('_ge_work_order_id',true));if(!$child_id)continue;$child=GE_Work_Finance::strict_order($child_id);$child->read_meta_data(true);GE_Work_History_Storage::check();if($child->get_meta('_ge_work_order',true)!=='yes' || (int)$child->get_meta('_ge_source_quote_order_id',true)!==$source_id || (int)$child->get_meta('_ge_source_quote_item_id',true)!==$id || $child->get_customer_id()!==$source->get_customer_id() || $child->get_currency()!==$source->get_currency())throw new DomainException('Revisá el vínculo del renglón con producción.');$transferred[(string)$child_id]=array('before'=>GE_Work_Historical_Reconciliation::snapshot($child,false),'source_order_id'=>$source_id,'source_item_id'=>$id);$child->update_meta_data('_ge_historical_original_source_order_id',$source_id);$child->update_meta_data('_ge_historical_original_source_item_id',$id);$child->update_meta_data('_ge_source_quote_order_id',$sale->get_id());$child->update_meta_data('_ge_source_quote_item_id',$map[(string)$id]);GE_Work_History_Storage::save_order_meta($child);GE_Work_History_Storage::check();$new_item=$sale->get_item($map[(string)$id]);$new_item->update_meta_data('_ge_work_order_id',$child_id);$new_item->save_meta_data();GE_Work_History_Storage::check();GE_Work_Finance::clear_order_cache($child_id);}
            $proof=array('source_order_id'=>(int)$source_id,'source_revision'=>$declaration['revision'],'source_key'=>$r['key'],'selected_items'=>$selected,'item_map'=>$map,'performed_cents'=>$r['performed_cents'],'adjustment_cents'=>$adjustment,'source_before'=>$before,'transferred_children'=>$transferred,'actor'=>get_current_user_id(),'recorded_at'=>gmdate('c'));
            $sale->update_meta_data(self::META,$proof);GE_Work_History_Storage::save_order_meta($sale);GE_Work_History_Storage::check();$source->update_meta_data('_ge_historical_scope_order_id',$sale->get_id());GE_Work_History_Storage::save_order_meta($source);GE_Work_History_Storage::check();GE_Work_History_Storage::commit();$started=false;GE_Work_Finance::clear_order_cache($source_id);GE_Work_Finance::clear_order_cache($sale->get_id());return wc_get_order($sale->get_id());
        }catch(Throwable $e){if($started)GE_Work_History_Storage::abort();GE_Work_Finance::clear_order_cache($source_id);if($sale instanceof WC_Order)GE_Work_Finance::clear_order_cache($sale->get_id());throw $e;}
        finally{GE_Work_Finance::unlock($key);}
    }
    public static function valid($order,$source) {
        $p=$order->get_meta(self::META,true);if(!is_array($p) || empty($p['actor']) || ($p['source_revision']??'')!==$source['revision'] || ($p['source_key']??'')!==$source['row']['key'] || (int)($p['source_order_id']??0)!==(int)$source['row']['order_id'] || ($p['performed_cents']??0)!==$source['row']['performed_cents'])return false;
        $origin=wc_get_order($p['source_order_id']);GE_Work_History_Storage::check();if(!$origin || (int)$origin->get_meta('_ge_historical_scope_order_id',true)!==$order->get_id() || $origin->get_customer_id()!==$order->get_customer_id() || $origin->get_currency()!==$order->get_currency())return false;
        $items=$order->get_items();if(count($items)!==count($p['item_map']))return false;foreach($p['item_map'] as $old_id=>$new_id){$item=$order->get_item($new_id);if(!$item || (int)$item->get_meta('_ge_historical_source_item_id',true)!==(int)$old_id)return false;}return true;
    }
}
